for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if str(uid) == "U_ALLARUS_CUSTODIANS_A" or str(u.get("flags", {}).get("cus11e_unleashed_from", "")) == "U_ALLARUS_CUSTODIANS_A":
		if u.models.size() != 1 or int(u.owner) != 1:
			return "bad unit " + str(uid)
		ids.append(str(uid))
return ids.size()

